CREATE OR REPLACE FUNCTION public.activate_group(p_group_id uuid, p_start_date date, p_force boolean DEFAULT false, p_allow_past boolean DEFAULT false, p_recompute_payouts boolean DEFAULT NULL::boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_group        susu_groups%ROWTYPE;
  v_mem          group_memberships%ROWTYPE;
  v_cashout      DECIMAL(10,2);
  v_total_days   INTEGER;
  v_paid_count   INTEGER;
  v_end_date     DATE;
  v_mem_start    DATE;
  v_offset       INTEGER;
  v_payout_date  DATE;
  v_payout_amt   DECIMAL(10,2);
  v_recompute    BOOLEAN;
  v_frac         NUMERIC(3,2);
BEGIN
  SELECT * INTO v_group FROM susu_groups WHERE id = p_group_id;
  IF v_group.id IS NULL THEN RAISE EXCEPTION 'Group not found'; END IF;

  IF v_group.status = 'completed' THEN
    RAISE EXCEPTION 'This group has completed and cannot be re-activated';
  END IF;

  IF p_start_date < CURRENT_DATE AND NOT p_allow_past THEN
    RAISE EXCEPTION 'Start date is in the past. Tick the confirmation to backdate a group that genuinely started on %.', p_start_date;
  END IF;

  IF v_group.status = 'active' AND NOT p_force THEN
    SELECT COUNT(*) INTO v_paid_count
    FROM contributions WHERE group_id = p_group_id AND status = 'paid';
    IF v_paid_count > 0 THEN
      RAISE EXCEPTION 'Group is already active with % paid contributions. Re-activating would rebuild the schedule and move collection dates.', v_paid_count;
    END IF;
  END IF;

  IF (SELECT COUNT(*) FROM group_memberships WHERE group_id = p_group_id AND status = 'active') = 0 THEN
    RAISE EXCEPTION 'Cannot activate a group with no active members';
  END IF;

  v_cashout    := COALESCE(v_group.cashout_amount,
                    v_group.contribution_amount * v_group.max_members * v_group.cycle_days);
  v_total_days := v_group.max_members * v_group.cycle_days;
  v_end_date   := p_start_date + v_total_days;
  v_recompute  := COALESCE(p_recompute_payouts, p_force);

  UPDATE susu_groups
  SET start_date = p_start_date, end_date = v_end_date, status = 'active'
  WHERE id = p_group_id;

  DELETE FROM contributions WHERE group_id = p_group_id AND status IN ('pending','overdue');
  DELETE FROM payouts       WHERE group_id = p_group_id AND status = 'upcoming';

  FOR v_mem IN
    SELECT * FROM group_memberships
    WHERE group_id = p_group_id AND status = 'active'
    ORDER BY payout_position
  LOOP
    v_mem_start := GREATEST(p_start_date, COALESCE(v_mem.joined_at::DATE, p_start_date));
    v_frac      := COALESCE(v_mem.slot_fraction, 1);

    IF v_recompute THEN
      v_payout_date := p_start_date + (v_mem.payout_position * v_group.cycle_days);
      v_payout_amt  := ROUND(v_cashout * v_frac, 2);
    ELSE
      v_payout_date := COALESCE(v_mem.payout_date,
                         p_start_date + (v_mem.payout_position * v_group.cycle_days));
      v_payout_amt  := COALESCE(v_mem.payout_amount, ROUND(v_cashout * v_frac, 2));
    END IF;

    UPDATE group_memberships
    SET payout_date = v_payout_date, payout_amount = v_payout_amt
    WHERE id = v_mem.id;

    IF NOT COALESCE(v_mem.payout_received, false) THEN
      INSERT INTO payouts (member_id, group_id, membership_id, total_amount, scheduled_date, status)
      VALUES (v_mem.member_id, p_group_id, v_mem.id, v_payout_amt, v_payout_date, 'upcoming');
    END IF;

    v_offset := v_mem_start - p_start_date;
    FOR i IN v_offset..(v_total_days - 1) LOOP
      IF NOT EXISTS (
        SELECT 1 FROM contributions
        WHERE membership_id = v_mem.id AND due_date = p_start_date + i
      ) THEN
        INSERT INTO contributions (member_id, group_id, membership_id, amount, due_date, status, cycle_number)
        VALUES (v_mem.member_id, p_group_id, v_mem.id,
                ROUND(v_group.contribution_amount * v_frac, 2),
                p_start_date + i, 'pending', FLOOR(i::FLOAT / v_group.cycle_days) + 1);
      END IF;
    END LOOP;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.change_admin_password(p_admin_id uuid, p_current text, p_new text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v_ok BOOLEAN;
BEGIN
  SELECT (password_hash = crypt(p_current, password_hash)) INTO v_ok
  FROM admin_users WHERE id = p_admin_id AND is_active = true;

  IF NOT COALESCE(v_ok, false) THEN RETURN false; END IF;

  IF length(p_new) < 10 THEN
    RAISE EXCEPTION 'Password must be at least 10 characters';
  END IF;
  IF p_new = 'Admin@1234' THEN
    RAISE EXCEPTION 'Choose a password that is not the shipped default';
  END IF;

  UPDATE admin_users
  SET password_hash        = crypt(p_new, gen_salt('bf')),
      must_change_password = false,
      token_version        = COALESCE(token_version, 0) + 1
  WHERE id = p_admin_id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_login_allowed(p_identifier text, p_kind text)
 RETURNS TABLE(allowed boolean, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_fails INTEGER;
  v_last  TIMESTAMPTZ;
BEGIN
  SELECT COUNT(*), MAX(attempted_at) INTO v_fails, v_last
  FROM login_attempts
  WHERE identifier = p_identifier AND kind = p_kind
    AND NOT succeeded AND attempted_at > NOW() - INTERVAL '15 minutes';

  IF v_fails >= 5 THEN
    RETURN QUERY SELECT false,
      GREATEST(0, EXTRACT(EPOCH FROM (v_last + INTERVAL '15 minutes' - NOW()))::INTEGER);
  ELSE
    RETURN QUERY SELECT true, 0;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_payout_eligibility(p_payout_id uuid)
 RETURNS TABLE(eligible boolean, reason text, gross_amount numeric, outstanding_contrib numeric, outstanding_penalty numeric, registration_fee numeric, net_amount numeric, contributions_paid integer, contributions_due integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_payout   payouts%ROWTYPE;
  v_group    susu_groups%ROWTYPE;
  v_out_c    DECIMAL := 0;
  v_out_p    DECIMAL := 0;
  v_paid     INTEGER := 0;
  v_due      INTEGER := 0;
  v_net      DECIMAL := 0;
  v_eligible BOOLEAN := true;
  v_reason   TEXT := 'Member is eligible for payout';
BEGIN
  SELECT * INTO v_payout FROM payouts WHERE id = p_payout_id;
  IF v_payout.id IS NULL THEN
    RETURN QUERY SELECT false, 'Payout not found'::TEXT, 0::DECIMAL, 0::DECIMAL, 0::DECIMAL, 0::DECIMAL, 0::DECIMAL, 0, 0;
    RETURN;
  END IF;

  SELECT * INTO v_group FROM susu_groups WHERE id = v_payout.group_id;

  -- Contributions for THIS slot only (fall back to member+group for any
  -- legacy payout row without a membership link)
  SELECT
    COALESCE(SUM(CASE WHEN status IN ('pending','overdue') THEN amount ELSE 0 END), 0),
    COUNT(CASE WHEN status = 'paid' THEN 1 END),
    COUNT(*)
  INTO v_out_c, v_paid, v_due
  FROM contributions
  WHERE (
      (v_payout.membership_id IS NOT NULL AND membership_id = v_payout.membership_id)
      OR
      (v_payout.membership_id IS NULL AND member_id = v_payout.member_id AND group_id = v_payout.group_id)
    )
    AND due_date <= v_payout.scheduled_date;

  -- Penalties: member+group; the release flow settles them so they only
  -- ever deduct once, on the first payout
  SELECT COALESCE(SUM(amount), 0) INTO v_out_p
  FROM payment_penalties
  WHERE member_id = v_payout.member_id
    AND group_id  = v_payout.group_id
    AND NOT is_paid;

  -- The registration fee is commission. It is NOT added here.
  v_net := v_payout.total_amount - v_out_c - v_out_p;

  IF v_out_c > 0 THEN
    v_eligible := false;
    v_reason := 'This slot has GHS ' || v_out_c::TEXT || ' in unpaid contributions due before its payout date';
  ELSIF v_out_p > 0 THEN
    v_eligible := true;
    v_reason := 'Eligible — GHS ' || v_out_p::TEXT || ' in penalties will be deducted';
  END IF;

  RETURN QUERY SELECT
    v_eligible, v_reason, v_payout.total_amount, v_out_c, v_out_p,
    COALESCE(v_group.registration_fee, 0),
    v_net, v_paid, v_due;
END;
$function$

CREATE OR REPLACE FUNCTION public.forfeit_membership(p_membership_id uuid, p_reason text, p_admin_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_m group_memberships%ROWTYPE;
  v_remaining INTEGER;
BEGIN
  SELECT * INTO v_m FROM group_memberships WHERE id = p_membership_id;
  IF v_m.id IS NULL THEN RAISE EXCEPTION 'Membership not found'; END IF;
  IF v_m.payout_received THEN RAISE EXCEPTION 'Cannot forfeit — member has already received their payout'; END IF;
  IF v_m.status = 'defaulted' THEN RAISE EXCEPTION 'This slot is already forfeited'; END IF;

  UPDATE group_memberships
  SET status = 'defaulted', forfeited_at = NOW(), forfeit_reason = p_reason
  WHERE id = p_membership_id;

  -- Free the slot in the group's live count (and reopen a full group)
  UPDATE susu_groups
  SET current_members = GREATEST(current_members - 1, 0),
      status = CASE WHEN status = 'full' THEN 'open' ELSE status END
  WHERE id = v_m.group_id;

  -- Cancel this slot's future contributions and upcoming payout only
  DELETE FROM contributions
  WHERE membership_id = p_membership_id AND status IN ('pending','overdue');
  DELETE FROM payouts
  WHERE membership_id = p_membership_id AND status = 'upcoming';

  -- Suspend the account ONLY if no active membership remains anywhere
  SELECT COUNT(*) INTO v_remaining
  FROM group_memberships
  WHERE member_id = v_m.member_id AND status = 'active';

  IF v_remaining = 0 THEN
    UPDATE members SET status = 'suspended' WHERE id = v_m.member_id;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_membership_schedule(p_membership_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_mem        group_memberships%ROWTYPE;
  v_group      susu_groups%ROWTYPE;
  v_frac       NUMERIC := 1;
  v_total_days INTEGER;
  v_mem_start  DATE;
  v_offset     INTEGER;
  v_inserted   INTEGER := 0;
BEGIN
  SELECT * INTO v_mem FROM group_memberships WHERE id = p_membership_id;
  IF v_mem.id IS NULL THEN RETURN 0; END IF;

  SELECT * INTO v_group FROM susu_groups WHERE id = v_mem.group_id;
  IF v_group.status <> 'active' OR v_group.start_date IS NULL THEN RETURN 0; END IF;

  -- slot_fraction arrived in v15; read it tolerantly so this works either way
  v_frac := COALESCE((to_jsonb(v_mem)->>'slot_fraction')::NUMERIC, 1);

  v_total_days := v_group.max_members * v_group.cycle_days;
  v_mem_start  := GREATEST(v_group.start_date, COALESCE(v_mem.joined_at::DATE, v_group.start_date));
  v_offset     := v_mem_start - v_group.start_date;
  IF v_offset < 0 THEN v_offset := 0; END IF;

  FOR i IN v_offset..(v_total_days - 1) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM contributions
      WHERE membership_id = p_membership_id AND due_date = v_group.start_date + i
    ) THEN
      INSERT INTO contributions (member_id, group_id, membership_id, amount, due_date, status, cycle_number)
      VALUES (v_mem.member_id, v_mem.group_id, p_membership_id,
              ROUND(v_group.contribution_amount * v_frac, 2),
              v_group.start_date + i, 'pending',
              FLOOR(i::FLOAT / v_group.cycle_days) + 1);
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  RETURN v_inserted;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_overdue_contributions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE updated_count INTEGER;
BEGIN
  UPDATE contributions
  SET status = 'overdue'
  WHERE status = 'pending' AND due_date < CURRENT_DATE;
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_login_attempt(p_identifier text, p_kind text, p_ok boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO login_attempts (identifier, kind, succeeded) VALUES (p_identifier, p_kind, p_ok);
  -- On success, clear the slate
  IF p_ok THEN
    DELETE FROM login_attempts
    WHERE identifier = p_identifier AND kind = p_kind AND NOT succeeded;
  END IF;
  -- Housekeeping
  DELETE FROM login_attempts WHERE attempted_at < NOW() - INTERVAL '24 hours';
END;
$function$

CREATE OR REPLACE FUNCTION public.record_partial_payment(p_contribution_id uuid, p_amount numeric, p_method text DEFAULT 'cash'::text, p_note text DEFAULT NULL::text)
 RETURNS TABLE(paid_so_far numeric, fully_paid boolean, amount_due numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_c contributions%ROWTYPE;
  v_new DECIMAL;
  v_done BOOLEAN;
BEGIN
  SELECT * INTO v_c FROM contributions WHERE id = p_contribution_id;
  IF v_c.id IS NULL THEN RAISE EXCEPTION 'Contribution not found'; END IF;

  v_new  := LEAST(v_c.amount, COALESCE(v_c.amount_paid, 0) + p_amount);
  v_done := v_new >= v_c.amount - 0.001;

  UPDATE contributions
  SET amount_paid = v_new,
      status = CASE WHEN v_done THEN 'paid' ELSE status END,
      paid_at = CASE WHEN v_done THEN NOW() ELSE paid_at END,
      payment_method = COALESCE(p_method, payment_method),
      payment_note = COALESCE(p_note, payment_note)
  WHERE id = p_contribution_id;

  RETURN QUERY SELECT v_new, v_done, v_c.amount;
END;
$function$

CREATE OR REPLACE FUNCTION public.session_is_current(p_id uuid, p_kind text, p_version integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE v INTEGER;
BEGIN
  IF p_kind = 'admin' THEN
    SELECT COALESCE(token_version, 0) INTO v FROM admin_users WHERE id = p_id AND is_active = true;
  ELSE
    SELECT COALESCE(token_version, 0) INTO v FROM members WHERE id = p_id AND status = 'active';
  END IF;
  IF v IS NULL THEN RETURN false; END IF;   -- deleted, suspended or deactivated
  RETURN v = COALESCE(p_version, 0);
END;
$function$
